fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> String {
    let p1 = a as i16;
    let t1 = b as i16;
    let p2 = c as i16;
    let t2 = d as i16;

    let score1 = std::cmp::max(
        3 * p1 / 10,
        p1 - p1 * t1 / 250
    );
    let score2 = std::cmp::max(
        3 * p2 / 10,
        p2 - p2 * t2 / 250
    );

    match score1.cmp(&score2) {
        std::cmp::Ordering::Greater => "Misha".to_string(),
        std::cmp::Ordering::Less => "Vasya".to_string(),
        std::cmp::Ordering::Equal => "Tie".to_string(),
    }
}